# %% [markdown]
# ## Step 3 — Fixed Chunking Strategy
#
# The simplest approach: split every N characters. Fast, but breaks mid-sentence and loses coherence.

# %%
def chunk_fixed(text, size=512, overlap=0):
    """Split text into fixed-size chunks (character-based)."""
    step = size - overlap
    return [text[i:i + size] for i in range(0, len(text), step)]

# Apply fixed chunking
fixed_chunks = chunk_fixed(contract_text, size=512, overlap=0)
print(f"Fixed chunking (512 chars, no overlap): {len(fixed_chunks)} chunks")
print(f"\nFirst chunk preview:\n{fixed_chunks[0][:200]}...")

# %% [markdown]
# ## Step 4 — Recursive Chunking (The 2026 Default)
#
# Recursive chunking tries splitting on paragraph, then sentence, then word boundaries. It preserves context better and is the production default.

# %%
def chunk_recursive(text, size=512, seps=("\n\n", "\n", ". ", " ")):
    """Recursively split on separators, preserving boundaries."""
    if len(text) <= size:
        return [text]
    for sep in seps:
        if sep not in text:
            continue
        parts = text.split(sep)
        chunks = []
        buf = ""
        for p in parts:
            if len(p) > size:
                if buf:
                    chunks.append(buf)
                    buf = ""
                chunks.extend(chunk_recursive(p, size=size, seps=seps[1:] or (" ",)))
                continue
            candidate = buf + sep + p if buf else p
            if len(candidate) <= size:
                buf = candidate
            else:
                if buf:
                    chunks.append(buf)
                buf = p
        if buf:
            chunks.append(buf)
        return [c for c in chunks if c.strip()]
    return chunk_fixed(text, size)

# Apply recursive chunking
recursive_chunks = chunk_recursive(contract_text, size=512)
print(f"Recursive chunking (512 chars): {len(recursive_chunks)} chunks")
print(f"\nFirst chunk preview:\n{recursive_chunks[0][:200]}...")

